/**
 * Recognise generated files and suggest how to change them properly.
 *
 * A file counts as generated when its path is a known output (lockfiles,
 * protobuf stubs, minified bundles, build output) or its header carries a
 * standard marker such as `@generated` or Go's `Code generated ... DO NOT
 * EDIT.`. Hand edits to such files are lost on the next regeneration or
 * leave them inconsistent with their source.
 */
import { matchesAny } from './shared/glob.ts'

/** Why a file is considered generated. */
export interface GeneratedInfo {
  /** `path` for a known output name, `marker` for a header marker. */
  via: 'path' | 'marker'
  /** The matching glob or marker line. */
  evidence: string
  /** How to make the change instead. */
  hint: string
}

/** Lockfiles and the command family that owns them. */
const LOCKFILES: Record<string, string> = {
  'package-lock.json': 'npm install / npm uninstall',
  'npm-shrinkwrap.json': 'npm install / npm uninstall',
  'pnpm-lock.yaml': 'pnpm add / pnpm remove / pnpm install',
  'yarn.lock': 'yarn add / yarn remove / yarn install',
  'bun.lock': 'bun add / bun remove / bun install',
  'bun.lockb': 'bun add / bun remove / bun install',
  'deno.lock': 'deno add / deno cache',
  'Cargo.lock': 'cargo add / cargo update -p <crate>',
  'poetry.lock': 'poetry add / poetry lock',
  'uv.lock': 'uv add / uv remove / uv lock',
  'Pipfile.lock': 'pipenv install / pipenv lock',
  'pdm.lock': 'pdm add / pdm lock',
  'composer.lock': 'composer require / composer update <pkg>',
  'Gemfile.lock': 'bundle add / bundle update <gem>',
  'go.sum': 'go get <module> / go mod tidy',
  'flake.lock': 'nix flake update / nix flake lock --update-input <input>',
  'Package.resolved': 'swift package update / resolve',
  'Podfile.lock': 'pod install / pod update <pod>',
  'pubspec.lock': 'dart pub add / dart pub upgrade',
  'mix.lock': 'mix deps.get / mix deps.update <dep>',
  'gradle.lockfile': './gradlew dependencies --write-locks',
  'packages.lock.json': 'dotnet add package / dotnet restore --force-evaluate',
  'conan.lock': 'conan lock create',
}

/** Default output globs (beyond lockfiles) with their regeneration hint. */
export const DEFAULT_GENERATED_GLOBS: Record<string, string> = {
  '*.pb.go': 'edit the .proto file and re-run protoc / buf generate',
  '*_pb2.py': 'edit the .proto file and re-run protoc / buf generate',
  '*_pb2_grpc.py': 'edit the .proto file and re-run protoc / buf generate',
  '*_pb2.pyi': 'edit the .proto file and re-run protoc / buf generate',
  '*.pb.h': 'edit the .proto file and re-run protoc / buf generate',
  '*.pb.cc': 'edit the .proto file and re-run protoc / buf generate',
  '*_grpc.pb.go': 'edit the .proto file and re-run protoc / buf generate',
  '*.g.dart': 'edit the annotated source and run `dart run build_runner build`',
  '*.freezed.dart': 'edit the annotated source and run `dart run build_runner build`',
  '*.Designer.cs': 'change it through the designer or the .resx/.settings source',
  '*.designer.cs': 'change it through the designer or the .resx/.settings source',
  '*.min.js': 'edit the unminified source and rebuild',
  '*.min.css': 'edit the unminified source and rebuild',
  '*.js.map': 'rebuild from source',
  '*.css.map': 'rebuild from source',
  '**/node_modules/**': 'change the dependency version or use patch-package / pnpm patch',
  '**/__generated__/**': 'edit the schema/source and re-run the code generator',
  '**/.next/**': 'edit the source; this is Next.js build output',
  '**/.nuxt/**': 'edit the source; this is Nuxt build output',
  '**/.svelte-kit/**': 'edit the source; this is SvelteKit build output',
  '**/dist/**': 'edit the source and rebuild; dist/ is build output',
  '**/target/**': 'edit the source and rebuild; target/ is build output',
  '**/.venv/**': 'change the dependency instead of editing the installed copy',
  '**/site-packages/**': 'change the dependency instead of editing the installed copy',
  '**/vendor/**': 'update the vendored dependency through its tool (go mod vendor, composer, bundler)',
}

const MARKERS: Array<[RegExp, string]> = [
  [/Code generated .*DO NOT EDIT\.?/i, 'go'],
  [/@generated\b/, 'generic'],
  [/\bDO NOT EDIT\b/i, 'generic'],
  [/\bauto-?generated\b|\bautomatically generated\b|\bmachine[- ]generated\b/i, 'generic'],
  [/\bThis (?:file|code) (?:is|was|has been) generated\b/i, 'generic'],
  [/\bGenerated by\s+[\w@./-]+/i, 'generic'],
  [/<auto-generated\s*\/?>|<auto-generated>/i, 'dotnet'],
]

const TOOL_HINTS: Array<[RegExp, string]> = [
  [/protoc|protobuf|buf generate|\.proto\b/i, 'edit the .proto source and re-run protoc / buf generate'],
  [/prisma/i, 'edit schema.prisma and run `prisma generate`'],
  [/graphql-codegen|@graphql-codegen|apollo/i, 'edit the GraphQL schema/operations and re-run graphql-codegen'],
  [/openapi|swagger|orval|openapi-typescript/i, 'edit the OpenAPI spec and re-run the client generator'],
  [/sqlc/i, 'edit the SQL queries/schema and run `sqlc generate`'],
  [/stringer|mockgen|go generate|ent\b|wire\b/i, 'edit the source and run `go generate ./...`'],
  [/drizzle/i, 'edit the drizzle schema and run `drizzle-kit generate`'],
  [/supabase/i, 'change the database and run `supabase gen types`'],
  [/thrift/i, 'edit the .thrift file and regenerate'],
  [/flatc|flatbuffers/i, 'edit the .fbs file and re-run flatc'],
  [/build_runner|json_serializable|freezed/i, 'edit the annotated source and run `dart run build_runner build`'],
  [/alembic/i, 'create a new migration with `alembic revision` instead of rewriting this one'],
  [/django/i, 'create a new migration with `manage.py makemigrations` instead of rewriting this one'],
  [/tsc|typescript|\.d\.ts/i, 'edit the .ts source and rebuild'],
  [/bindgen|cbindgen/i, 'edit the header/Rust source and regenerate the bindings'],
]

/**
 * Pick the most specific regeneration hint for a marker header.
 * @param header - the first lines of the file.
 * @returns hint text.
 */
export function hintFor(header: string): string {
  const from = /generated (?:by .+? )?from\s+[`'"]?([\w./@-]+\.\w+)/i.exec(header)
  for (const [re, hint] of TOOL_HINTS) if (re.test(header)) return from === null ? hint : `${hint} (source: ${from[1]})`
  if (from !== null) return `edit ${from[1]} and re-run the generator`
  const by = /generated by\s+[`'"]?([\w@./-]+)/i.exec(header)
  if (by !== null) return `change the input and re-run ${by[1]}`
  return 'find the generator or source this file comes from, change that, and regenerate'
}

/** Detection options. */
export interface GeneratedOptions {
  /** Extra globs → hint. */
  extraGlobs?: Readonly<Record<string, string>>
  /** Globs to never treat as generated (wins over everything). */
  ignore?: readonly string[]
  /** Disable the default output globs (lockfiles stay on). */
  defaultGlobs?: boolean
  /** Number of leading lines searched for markers. */
  headerLines?: number
}

/**
 * Decide whether a file is generated.
 * @param relative - workspace-relative POSIX path.
 * @param content - current file content, or undefined when unknown/new.
 * @param options - extra globs, ignore list, header size.
 * @returns why it is generated, or undefined.
 */
export function generatedInfo(relative: string, content: string | undefined, options: GeneratedOptions = {}): GeneratedInfo | undefined {
  if (options.ignore !== undefined && options.ignore.length > 0 && matchesAny(relative, options.ignore)) return undefined
  const base = relative.split('/').at(-1) ?? relative
  const lock = LOCKFILES[base]
  if (lock !== undefined) {
    return { via: 'path', evidence: base, hint: `change dependencies with \`${lock}\` and let the package manager rewrite ${base}; to resolve a lockfile merge conflict, check out one side and re-run install` }
  }
  const globs: Record<string, string> = { ...(options.defaultGlobs === false ? {} : DEFAULT_GENERATED_GLOBS), ...options.extraGlobs }
  for (const [glob, hint] of Object.entries(globs)) {
    if (matchesAny(relative, [glob])) return { via: 'path', evidence: glob, hint }
  }
  if (content === undefined) return undefined
  const header = content.split(/\r?\n/, options.headerLines ?? 15).join('\n').slice(0, 4000)
  for (const [re] of MARKERS) {
    const m = re.exec(header)
    if (m === null) continue
    const line = header.split('\n').find(l => re.test(l))?.trim() ?? m[0]
    // "Generated by" alone is weak; require it to sit in a comment-looking line.
    if (re.source.startsWith('\\bGenerated by') && !/^\s*(?:\/\/|#|\/\*|\*|<!--|--|;)/.test(line)) continue
    return { via: 'marker', evidence: line.slice(0, 160), hint: hintFor(header) }
  }
  return undefined
}
